const extractApiError=(e:unknown):string=>{const err=typeof e==='object'&&e!==null?e as {response?:{data?:unknown};data?:unknown;body?:unknown}:{};for(const c of [err.response?.data,err.data,err.body])if(typeof c==='object'&&c!==null){const p=c as {error?:string;stage?:string;providerStatus?:number|null;providerBody?:string|null};if(p.error){const bits=[p.stage?`[${p.stage}]`:'',p.error];if(typeof p.providerStatus==='number')bits.push(`(provider HTTP ${p.providerStatus})`);if(p.providerBody)bits.push(`— ${String(p.providerBody).slice(0,500)}`);return bits.filter(Boolean).join(' ')}}return e instanceof Error&&e.message?e.message:'unknown_error'};
